/* AI proposal review and opt-in server team tools. No synthetic live-service success. */
const StudioServices=(()=>{
 function recipe(value){
  if(!value||typeof value!=='object'||Object.keys(value).sort().join(',')!=='depth,holes,name,outline,plane'||typeof value.name!=='string'||!value.name.trim()||value.name.length>80||!Array.isArray(value.holes)||value.holes.length>8)throw Error('Use a named polygon recipe with depth, plane, outline and up to eight holes.');
  const model={version:1,plane:value.plane,outline:value.outline,features:value.holes.map((h,i)=>{if(!h||Object.keys(h).sort().join(',')!=='diameter,u,v')throw Error('Invalid hole fields.');return {id:'proposal-hole-'+i,name:'Proposed hole '+(i+1),enabled:true,operation:'subtract',shape:'cylinder',dims:{diameter:h.diameter,depth:value.depth},position:[h.u,h.v,0],rotation:[0,0,0],through:true};})};if(!StudioSolidModel.validate(model,value.depth))throw Error('Invalid model recipe.');return {name:value.name.trim(),depth:value.depth,model};
 }
 function open({modelPart}){
  const projectId=current.id;
  modal('AI modelling & project team',`<p>AI proposes a polygon extrusion with round holes. You review and edit its geometry before applying it. A proposal never changes the project automatically.</p><label>Describe a part<textarea id="aiModelPrompt" maxlength="2000" rows="3" placeholder="An 80 × 50 × 8 mm plate with two 6 mm mounting holes"></textarea></label><p class="tiny">${studioBackend.aiProvider==='ollama'?'A request sends this prompt to the Ollama model running on this computer. No cloud fallback is used.':'A live request sends this prompt to the configured AI provider through your server.'} Project notes, mesh files and account details are not attached.</p><button type="button" id="requestModelProposal" ${studioBackend.enabled&&studioBackend.ai?'':'disabled'}>Request Pro AI proposal</button><p>${studioBackend.enabled?'Live generation requires configured AI and an active Pro entitlement.':'Device mode: live AI and teams require the deployed account backend.'}</p><details><summary>Manual recipe preview · no AI request</summary><textarea id="manualRecipe" rows="8" spellcheck="false" aria-label="Manual model recipe">${esc(JSON.stringify({name:'Mounting plate proposal',depth:8,plane:'XZ',outline:[[-40,-25],[40,-25],[40,25],[-40,25]],holes:[{diameter:6,u:-25,v:0},{diameter:6,u:25,v:0}]},null,2))}</textarea><button type="button" id="previewManualRecipe">Validate & preview recipe</button></details><hr><h3>Team collaboration</h3><p>Pro owners can invite existing verified accounts as viewers or editors. Recipients accept in-app. Open a shared 3D workspace for presence, transform edits and object-level conflict merging.</p><button type="button" id="openLiveTeam" ${studioBackend.enabled?'':'disabled'}>Open shared 3D workspace</button><button type="button" id="manageProjectTeam" ${studioBackend.enabled?'':'disabled'}>Manage this project’s team</button><button type="button" id="viewTeamInbox" ${studioBackend.enabled?'':'disabled'}>Invitations & shared projects</button><p id="servicesError" role="alert"></p>`,()=>false);
  document.querySelector('#modalForm>button[type=submit]').textContent='Close';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();document.getElementById('dialog').close();};
  const servicePanel=document.getElementById('manualRecipe');const review=async draft=>{if(!servicePanel.isConnected||!document.getElementById('dialog').open)throw Error('Proposal review was cancelled.');if(current.id!==projectId)throw Error('The active project changed. Reopen this tool.');await StudioSolidModel.prepare(draft.model,draft.depth);if(current.id!==projectId||!servicePanel.isConnected||!document.getElementById('dialog').open)throw Error('The project or active tool changed. Reopen the proposal.');await new Promise(resolve=>{const dialog=document.getElementById('dialog');dialog.addEventListener('close',resolve,{once:true});dialog.close();});StudioSolidEditor.open({...draft,isNew:true,onCommit:async next=>{if(current.id!==projectId)throw Error('The active project changed. Reopen the proposal.');await modelPart(next);}});};
  document.getElementById('previewManualRecipe').onclick=async()=>{try{const raw=document.getElementById('manualRecipe').value;if(raw.length>32000)throw Error('Keep the recipe below 32 KB.');await review(recipe(JSON.parse(raw)));}catch(e){const error=document.getElementById('servicesError');if(error)error.textContent=e.message;else toast(e.message);}};
  document.getElementById('requestModelProposal').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const prompt=document.getElementById('aiModelPrompt').value.trim();if(!prompt)throw Error('Describe the proposed part first.');await studioBackend.flush();const version=current.version;const response=await studioBackend.request('/projects/'+encodeURIComponent(projectId)+'/model-proposal','POST',{prompt,version});if(current.id!==projectId||current.version!==response.project_version)throw Error('Project changed during generation. Request a fresh proposal.');await review(response.proposal);}catch(e){const error=document.getElementById('servicesError');if(error)error.textContent=e.message;else toast(e.message);}finally{if(button.isConnected)button.disabled=false;}};
  document.getElementById('openLiveTeam').onclick=()=>StudioTeamWorkspace.open(projectId).catch(e=>toast(e.message));document.getElementById('manageProjectTeam').onclick=()=>team(projectId);document.getElementById('viewTeamInbox').onclick=inbox;
 }
 async function team(id){try{
  await studioBackend.flush();const base='/team/projects/'+encodeURIComponent(id);
  const [members,pending,comments]=await Promise.all([studioBackend.request(base+'/members'),studioBackend.request(base+'/invitations'),studioBackend.request(base+'/comments')]);
  modal('Project team',`<p>Invitations are in-app only and expire in seven days. Pending emails are shown exactly as invited, whether or not an account exists. Only accepted collaborators disclose their account membership.</p><label>Recipient email<input id="teamEmail" type="email" required></label><label>Role<select id="teamRole"><option value="viewer">Viewer + comments</option><option value="editor">Editor + comments</option></select></label><button type="button" id="inviteProjectMember">Create in-app invitation</button><h3>Accepted collaborators</h3><div>${members.map(m=>`<p>${esc(m.email)} · ${esc(m.role)} <button type="button" data-revoke-team="${esc(m.user_id)}">Revoke access</button></p>`).join('')||'No accepted collaborators yet.'}</div><h3>Pending invitations</h3><div>${pending.map(m=>`<p>${esc(m.email)} · ${esc(m.role)} · awaiting acceptance <button type="button" data-revoke-invite="${esc(m.id)}">Cancel invitation</button></p>`).join('')||'No pending invitations.'}</div><h3>Comments</h3><div>${comments.map(c=>`<p><b>${esc(c.author)}</b>: ${esc(c.body)}</p>`).join('')||'No comments.'}</div><label>New comment<textarea id="teamComment" maxlength="2000"></textarea></label><button type="button" id="postOwnerComment">Post comment</button><p id="teamStatus" role="status"></p>`,()=>false);
  document.querySelector('#modalForm>button[type=submit]').textContent='Close';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();document.getElementById('dialog').close();};
  const run=async fn=>{try{await fn();await team(id);}catch(e){document.getElementById('teamStatus').textContent=e.message;}};
  document.getElementById('inviteProjectMember').onclick=()=>run(()=>studioBackend.request(base+'/members','POST',{email:document.getElementById('teamEmail').value,role:document.getElementById('teamRole').value}));
  document.getElementById('postOwnerComment').onclick=()=>run(()=>studioBackend.request(base+'/comments','POST',{body:document.getElementById('teamComment').value}));
  document.querySelectorAll('[data-revoke-team]').forEach(b=>b.onclick=()=>run(()=>studioBackend.request(base+'/members/'+encodeURIComponent(b.dataset.revokeTeam),'DELETE')));
  document.querySelectorAll('[data-revoke-invite]').forEach(b=>b.onclick=()=>run(()=>studioBackend.request(base+'/invitations/'+encodeURIComponent(b.dataset.revokeInvite),'DELETE')));
 }catch(e){toast(e.message);}}
 async function inbox(){try{const [invites,shared]=await Promise.all([studioBackend.request('/team/invitations'),studioBackend.request('/team/projects')]);modal('Team invitations & projects',`${invites.map(p=>`<p>${esc(p.name)} · ${esc(p.role)} <button type="button" data-accept-team="${esc(p.project_id)}">Accept invitation</button></p>`).join('')||'<p>No pending invitations.</p>'}<h3>Shared with you</h3>${shared.map(p=>`<p>${esc(p.name)} · ${esc(p.role)} <button type="button" data-open-team="${esc(p.id)}">Open shared 3D</button><button type="button" data-json-team="${esc(p.id)}">JSON & comments</button></p>`).join('')||'<p>No accepted projects.</p>'}`,()=>false);document.querySelector('#modalForm>button[type=submit]').textContent='Close';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();document.getElementById('dialog').close();};document.querySelectorAll('[data-accept-team]').forEach(b=>b.onclick=async()=>{try{await studioBackend.request('/team/projects/'+b.dataset.acceptTeam+'/accept','POST',{});await inbox();}catch(e){toast(e.message);}});document.querySelectorAll('[data-open-team]').forEach(b=>b.onclick=()=>StudioTeamWorkspace.open(b.dataset.openTeam).catch(e=>toast(e.message)));;document.querySelectorAll('[data-json-team]').forEach(b=>b.onclick=()=>reviewShared(b.dataset.jsonTeam));}catch(e){toast(e.message);}}
 async function reviewShared(id){try{const {project,role}=await studioBackend.request('/team/projects/'+id),comments=await studioBackend.request('/team/projects/'+id+'/comments');modal('Review shared project',`<p>${esc(project.name)} · ${esc(role)} · version ${project.version}. Download a copy to inspect it in your personal workspace. Editors can explicitly submit project JSON; concurrent changes are rejected.</p><button type="button" id="downloadTeamProject">Download current draft / project copy</button>${role==='editor'?`<label>Versioned project JSON<textarea id="teamProjectJson" rows="10" spellcheck="false">${esc(JSON.stringify(project,null,2))}</textarea></label><button type="button" id="saveTeamJson">Submit shared project changes</button>`:''}<h3>Comments</h3>${comments.map(c=>`<p><b>${esc(c.author)}</b>: ${esc(c.body)}</p>`).join('')}<label>New comment<textarea id="reviewComment" maxlength="2000"></textarea></label><button type="button" id="postReviewComment">Post comment</button><p id="reviewStatus" role="status"></p>`,()=>false);document.querySelector('#modalForm>button[type=submit]').textContent='Close';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();document.getElementById('dialog').close();};document.getElementById('downloadTeamProject').onclick=()=>download('shared-project-copy.json',document.getElementById('teamProjectJson')?.value||JSON.stringify(project,null,2),'application/json');const run=async fn=>{try{await fn();await reviewShared(id);}catch(e){document.getElementById('reviewStatus').textContent=e.message;}};document.getElementById('postReviewComment').onclick=()=>run(()=>studioBackend.request('/team/projects/'+id+'/comments','POST',{body:document.getElementById('reviewComment').value}));if(role==='editor')document.getElementById('saveTeamJson').onclick=()=>run(()=>{const raw=document.getElementById('teamProjectJson').value;if(raw.length>900000)throw Error('Keep the project payload below 900 KB.');const next=StudioProjectData.parse(raw);if(!StudioProjectData.validate(next))throw Error('Invalid project data.');return studioBackend.request('/team/projects/'+id,'PATCH',next);});}catch(e){toast(e.message);}}
 return {open,recipe,inbox};
})();
